:root {
  /* Colors */
  --color-ember-signal: #ff3c00;
  --color-peach-glow: #ffb199;
  --color-linen-canvas: #f6f5f4;
  --color-stone-band: #f1f0ee;
  --color-paper: #ffffff;
  --color-cream-footer: #faf5f0;
  --color-onyx-pill: #181818;
  --color-graphite-ink: #312e2e;
  --color-charcoal-nav: #37383c;
  --color-slate-caption: #4b5563;
  --color-pebble-hint: #6f6c6a;
  --color-quartz-border: #dbd9d3;
  --color-mist-hairline: #c5c5c599;

  /* Typography — Font Families */
  --font-replit-diatype: "Replit Diatype", "Inter Display", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-replit-diatype-mono: "Replit Diatype Mono", "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.5;
  --tracking-small: 0px;
  --text-caption: 13px;
  --leading-caption: 1.2;
  --tracking-caption: 1.56px;
  --text-body: 14px;
  --leading-body: 1.714;
  --tracking-body: 0px;
  --text-subheading: 20px;
  --leading-subheading: 1.4;
  --tracking-subheading: 0px;
  --text-heading-sm: 26px;
  --leading-heading-sm: 1.2;
  --tracking-heading-sm: -0.78px;
  --text-heading: 36px;
  --leading-heading: 1;
  --tracking-heading: -1.08px;
  --text-heading-lg: 48px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: -2.88px;
  --text-display: 64px;
  --leading-display: 1;
  --tracking-display: -3.84px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-regular-2: 450;
  --font-weight-regular-3: 460;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-120: 120px;

  /* Layout */
  --page-max-width: 1380px;
  --section-gap: 120px;
  --section-gap-mobile: 64px;
  --card-padding: 24px;
  --element-gap: 8px;
  --nav-height: 80px;
  --control-height: 38px;
  --control-height-sm: 32px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-3xl: 24px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-tags: 4px;
  --radius-nav: 6px;
  --radius-inputs: 6px;
  --radius-buttons: 8px;
  --radius-small-cards: 8px;
  --radius-inner-tiles: 12px;
  --radius-cards: 16px;
  --radius-sections: 24px;
  --radius-pills: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: inset 0 0 0 1px rgb(219, 218, 211), 0 1px 2px 0 rgba(0, 0, 0, 0.02);
  --shadow-sm: inset 0 0 0 1px rgb(216, 224, 228);
  --shadow-md: 0 8px 24px 0 rgba(0, 0, 0, 0.12);

  /* Surfaces */
  --surface-linen-canvas: #f6f5f4;
  --surface-stone-band: #f1f0ee;
  --surface-cream-footer: #faf5f0;
  --surface-paper: #ffffff;
  --surface-onyx-pill: #181818;
}

